package com.railway.servlet;import jakarta.servlet.*;import jakarta.servlet.http.*;import java.io.IOException;import java.sql.*;import java.util.*;import com.railway.model.User;import com.railway.util.DB;
public class MyBookingsServlet extends HttpServlet {protected void doGet(HttpServletRequest r,HttpServletResponse s)throws ServletException,IOException{User u=(User)r.getSession(false).getAttribute("user");List<Map<String,Object>> rows=new ArrayList<>();try(Connection c=DB.getConnection();PreparedStatement p=c.prepareStatement("SELECT b.pnr,b.status,b.total_fare,b.passenger_count,sc.journey_date,t.train_name,t.source,t.destination FROM bookings b JOIN train_schedules sc ON sc.id=b.schedule_id JOIN trains t ON t.id=sc.train_id WHERE b.user_id=? ORDER BY b.created_at DESC")){p.setLong(1,u.getId());try(ResultSet x=p.executeQuery()){while(x.next()){Map<String,Object> m=new HashMap<>();for(String k:List.of("pnr","status","total_fare","passenger_count","journey_date","train_name","source","destination"))m.put(k,x.getObject(k));rows.add(m);}}}catch(Exception e){getServletContext().log("Booking history failed",e);r.setAttribute("error","Could not load bookings.");}r.setAttribute("bookings",rows);r.getRequestDispatcher("/my-bookings.jsp").forward(r,s);}}
